const i = $input.first().json;

// `keywords` may arrive as a real array or as a JSON string, depending on how the
// caller mapped it through the Execute Workflow node. Both are accepted.
const parse = v => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim().startsWith('[')) {
    try { return JSON.parse(v); } catch (e) { return []; }
  }
  return [];
};
const clean = v => parse(v).map(s => String(s ?? '').trim()).filter(Boolean);

const style = String(i.style ?? '').trim() || 'beer';

// ⛔ Sensory descriptors must not reach the retriever. `bitter` matches 520 chunks
// and `sweet` 301 (measured 2026-09-17), so searching them returns whatever sits
// nearest the bare word, not anything about the brief. Document frequency cannot
// separate them automatically -- `thick` (47) and `vanilla` (37) overlap -- so the
// caller names them in `exclude` and they are dropped here.
const excl = new Set(clean(i.exclude).map(s => s.toLowerCase()));

let terms = [];
const seen = new Set();
for (const t of clean(i.keywords)) {
  const k = t.toLowerCase();
  if (excl.has(k) || seen.has(k)) continue;
  seen.add(k);
  terms.push(t);
}

// Collapse a longer term onto a shorter one it contains: "crushed poppy seeds" and
// "poppy seeds" are the same search, and the shorter retrieves better in both arms.
// ⛔ Case is preserved on whatever survives. nlq.corpus_vocabulary_gap's phrase arm
// keys on a leading capital, so lowercasing here would hide product names from the
// gap detector inside wf-step-retrieve.
terms = terms.filter(t =>
  !terms.some(o => o.length < t.length && t.toLowerCase().includes(o.toLowerCase())));

if (!terms.length) terms = [style];

const k = Number(i.top_k);
const mode = String(i.mode ?? 'text').trim().toLowerCase() === 'rows' ? 'rows' : 'text';

return [{ json: {
  terms,
  style,
  mode,
  session_id: String(i.session_id ?? '').trim(),
  top_k: Number.isFinite(k) && k > 0 ? Math.min(Math.round(k), 8) : 8,
}}];

const src = $('Normalise input').first().json;

// Probe rows come back unordered (DISTINCT); re-key them against the normalised
// term list so the caller's order survives into the query and the citations.
const hits = new Map();
for (const it of $input.all()) {
  if (it.json.term == null) continue;
  hits.set(String(it.json.term), Number(it.json.fts_hits) || 0);
}

const covered   = src.terms.filter(t => (hits.get(t) ?? 0) > 0);
const uncovered = src.terms.filter(t => (hits.get(t) ?? 0) === 0);

// ⛔ wf-step-retrieve THROWS on an empty query. When the library covers none of the
// keywords the style is all that is left to search on, and it is never empty --
// Normalise input defaults it to 'beer'.
const query = covered.join(' ') || src.style;

return [{ json: { ...src, covered, uncovered, query } }];

const src = $('Split coverage').first().json;

// Capped at 3. Each call is a live SearXNG round trip plus page fetches -- measured
// 12.2 s for one on 2026-09-17 -- so the cap is a latency budget, not a quality
// judgement. Same cap as Plan parts in wf-step-retrieve-multi.
return src.uncovered.slice(0, 3).map(term => ({ json: {
  term,
  // A bare keyword is a bad web query. Frame it as the brewer would have asked.
  web_query: `${term} ${src.style} homebrew how much to use and when to add`,
}}));

const src  = $('Split coverage').first().json;
const mode = String(src.mode ?? 'text').toLowerCase() === 'rows' ? 'rows' : 'text';

// wf-step-retrieve was called with mode:'rows', so it returns one item carrying the
// structured rows. Always Output Data is ON inside it, so a zero-row search arrives
// as an empty array rather than as no item at all.
const libr = $('Library search').first().json ?? {};
const rows = (libr.rows ?? []).filter(r => r && r.chunk_id != null);

// ⛔ `Web gaps` only runs on the true arm, so referencing it on the false arm THROWS
// rather than returning empty. try/catch is load-bearing -- the same reason it is in
// wf-step-retrieve's Return rows. onError:continueRegularOutput also means a failed
// call arrives carrying `error` and no `rows`; that is treated as no web results.
let web = [];
try {
  const seen = new Set();
  for (const it of $('Web gaps').all()) {
    for (const r of (it.json?.rows ?? [])) {
      if (!r || seen.has(r.url)) continue;   // one passage per source
      seen.add(r.url);
      web.push(r);
    }
  }
} catch (e) { /* gate was false: no web arm on this path */ }

const gap   = src.uncovered;
const asked = src.covered.length
  ? src.covered.map(t => `"${t}"`).join(', ')
  : `"${src.query}"`;

// Structured shape -- for capabilities. Empty is a valid answer, not an error.
if (mode === 'rows') {
  return [{ json: {
    query: src.query, count: rows.length,
    covered: src.covered, gap, web, rows,
  }}];
}

// Text shape -- for the model. ONE item, ONE key. Mirrors wf-step-retrieve's
// Return rows; a caller must not be able to tell which retriever it reached.
if (!rows.length && !web.length) {
  return [{ json: { response: `No passages in the library matched ${asked}.` } }];
}

const libraryBlock = rows.length
  ? `${rows.length} passages from the library for ${asked}:\n\n` +
    rows.map((x, n) =>
      `[S${n + 1}] ${x.doc_title} · ${x.heading}${x.page ? ` · p.${x.page}` : ''}\n${x.text}`
    ).join('\n\n')
  : `No passages in the library matched ${asked}.`;

if (!web.length) {
  const why = gap.length
    ? `\n\nThe library does not cover ${gap.map(t => `"${t}"`).join(', ')}, and no usable web source was reachable.`
    : '';
  return [{ json: { response: libraryBlock + why } }];
}

// ⛔ [W..] is a DIFFERENT marker from [S..] on purpose, and the sentence below is an
// instruction the model reads, not decoration. Web passages carry none of the
// library's editorial vetting and must never be presented as though they do.
const webBlock = web.map((x, n) =>
  `[W${n + 1}] ${x.url}${x.heading ? ` · ${x.heading}` : ''}\n${x.text}`
).join('\n\n');

return [{ json: {
  response: `${libraryBlock}\n\n---\n` +
    `Your library has never seen ${gap.map(t => `"${t}"`).join(', ')}, so these came from the web.\n` +
    `Cite them as [W1], [W2] — NOT as [S1] — and tell the reader plainly that this ` +
    `part is from the web and is not in their library.\n\n${webBlock}`,
}}];
